const stars = (c, r, w, h, n) => { for (let i = 0; i < n; i++) { const s = r() < .1 ? 3 : 2; c.fillStyle = `rgba(255,255,255,${r.range(.12, .7)})`; c.fillRect(r() * w, r() * h, s, s); } };
