  P2.fillStrokes(c, r, [0, y0, W, y1 - y0], o.inside || (() => true), { n: o.n ?? 8000, len: [30, 150], w: [2, 6], ang: 0, angJ: .03, al: o.al ?? .3, colFn: (x, y) => P2.jitter(P2.mix(top, bot, (y - y0) / (y1 - y0)), r, o.var ?? 12) });
